  const [infoR, reactR, reviewsR, threadsR, issuesR] = await Promise.all([
    tools.mcp__codex_apps__github_get_pr_info({repository_full_name:"scottdensmore/travel-app",pr_number:pr}),
    tools.mcp__codex_apps__github_get_pr_reactions({repo_full_name:"scottdensmore/travel-app",pr_number:pr,per_page:100,page:1}),
