    tools.mcp__codex_apps__github_fetch_issue_comments({repo_full_name:"scottdensmore/travel-app",issue_number:pr})
  ]);
  const info=sc(infoR), react=sc(reactR), rev=sc(reviewsR), th=sc(threadsR), iss=sc(issuesR);
  const reviews=(rev?.reviews??[]).map(x=>({
    author:x.author?.login,state:x.state,submitted_at:x.submitted_at,
    reviewed_commit:(x.body?.match(/Reviewed commit:\*\* `([^`]+)/)||[])[1]??null,
    headline:firstLine(x.body)
  }));
  const threads=(th?.review_threads??[]).map(x=>({
    resolved:x.is_resolved,outdated:x.is_outdated,path:x.path,
    created_at:x.comments?.[0]?.created_at,
    author:x.comments?.[0]?.author?.login,
    headline:firstLine(x.comments?.[0]?.body)
  }));
  const comments=(iss?.comments??iss?.issue_comments??iss?.result?.comments??[]).map(x=>({
    author:x.user?.login??x.author?.login,
    created_at:x.created_at,
    body:firstLine(x.body)
  }));
  return {
    pr, head_sha:info?.head_sha, commits:info?.commits, created_at:info?.created_at, merged_at:info?.merged_at,
    reactions:(react?.reactions??[]).map(x=>({author:x.user?.login,content:x.content,created_at:x.created_at})),
    reviews, threads, issue_comments:comments
  };
}));
